//! `settle` against `tests/vectors/settle/*.json`, and whole-market traces of `observe`,
//! `persist`, `bounds` and `settle` together, generated by `gen_settle.py` from
//! `shortwin_sim.py` v0.4.1 with its default switches and the attack scripts of
//! `sim/attacks/` (ARCHITECTURE §8.1, §9 M0b).
//!
//! * `units_settle.json`: the sim's `settle_box` (also with a depth cap, AIR-15) and `_s3_due`
//!   on synthetic states.
//! * `units_evaluate_*.json`: the sim's `try_exit(settle_only = True)` on synthetic states
//!   with quotes drawn around every decision boundary.
//! * `trace_{attacks,scenarios,random}_*.json`: full replays of one market lineage each —
//!   every observation, roll (with its pre-roll gap), venue change, persistence check,
//!   exit reference, `max_in` and settlement evaluation; the replayed state is compared with
//!   the sim's at every step (box, EMA state, arm state, periodic full-state checkpoints).
//! * `fuzz_*.json`: ECON §13's exit fuzz (`fuzz_exits(1000, 20260927)`, asserted against
//!   ECON's published statistics by the generator), decision-only: each settlement
//!   evaluation is self-contained (the sim's box, legs, quotes and arm state), so the
//!   decisions of all 1,000 paths are checked without replaying 10⁶ observations.
//!
//! Quotes are the sim's own values at the points a decision may read (the box corners, the
//! robust spot, the EMA point), served by [`TableQuotes`]: a point the crate asks for that
//! the sim's rule does not read fails the test, so the corner choice is checked too. Every
//! comparison is exact.
#![allow(clippy::unwrap_used, clippy::arithmetic_side_effects)]

mod common;

use std::collections::HashMap;
use std::fmt::Debug;
use std::str::{FromStr, SplitWhitespace};

use serde::Deserialize;
use shortwin_math::bounds::{
    ExitParams, expiry_reference, liq_reference, max_in_exp, max_in_liq, pi_ref, ref_liquidity,
};
use shortwin_math::observe::{
    Bucket, EmaParams, LastBucket, Observation, Ring, RingEntry, VenueChange, ring_medians,
    robust_spot, sustained_growth,
};
use shortwin_math::persist::liq_ema_leg;
use shortwin_math::risk::{Budget, SettleKind};
use shortwin_math::settle::{
    ArmChange, ArmState, BoxQuotes, DisarmReason, S3Chain, S3Terms, SettleBox, SettleInputs,
    SettleTerms, box_of, box_of_capped, evaluate, not_liquidatable, refuted, s1_legs, s2_legs,
    s3_due,
};
use shortwin_math::{MathError, U256};

// ---------------------------------------------------------------------------------------
// Token parsing
// ---------------------------------------------------------------------------------------

struct Toks<'a> {
    it: SplitWhitespace<'a>,
    src: &'a str,
}

impl<'a> Toks<'a> {
    fn new(src: &'a str) -> Self {
        Self {
            it: src.split_whitespace(),
            src,
        }
    }

    fn s(&mut self) -> &'a str {
        self.it
            .next()
            .unwrap_or_else(|| panic!("vector line too short: {}", self.src))
    }

    fn parse<T: FromStr>(&self, s: &str) -> T
    where
        T::Err: Debug,
    {
        s.parse()
            .unwrap_or_else(|e| panic!("bad token {s:?} ({e:?}) in: {}", self.src))
    }

    fn v<T: FromStr>(&mut self) -> T
    where
        T::Err: Debug,
    {
        let s = self.s();
        self.parse(s)
    }

    /// `-` is `None`.
    fn opt<T: FromStr>(&mut self) -> Option<T>
    where
        T::Err: Debug,
    {
        match self.s() {
            "-" => None,
            s => Some(self.parse(s)),
        }
    }

    /// `.` (not recorded) is `None`, `-` is `Some(None)`.
    fn rec<T: FromStr>(&mut self) -> Option<Option<T>>
    where
        T::Err: Debug,
    {
        match self.s() {
            "." => None,
            "-" => Some(None),
            s => Some(Some(self.parse(s))),
        }
    }

    fn rest<T: FromStr>(&mut self) -> Option<T>
    where
        T::Err: Debug,
    {
        let s = self.it.next()?;
        Some(self.parse(s))
    }

    fn b(&mut self) -> bool {
        match self.s() {
            "1" => true,
            "0" => false,
            s => panic!("bad bool {s:?} in: {}", self.src),
        }
    }

    /// `.` (not evaluated) is `None`.
    fn ob(&mut self) -> Option<bool> {
        match self.s() {
            "." => None,
            "1" => Some(true),
            "0" => Some(false),
            s => panic!("bad bool {s:?} in: {}", self.src),
        }
    }

    fn bar(&mut self) {
        assert_eq!(self.s(), "|", "separator expected in: {}", self.src);
    }

    fn done(&mut self) {
        assert!(self.it.next().is_none(), "trailing tokens in: {}", self.src);
    }
}

/// `n × (ts p l x y lo hi llo lhi)`, oldest first.
fn parse_ring(t: &mut Toks) -> Ring {
    let n: usize = t.v();
    let mut ring = Ring::default();
    for _ in 0..n {
        ring.push(RingEntry {
            ts: t.v(),
            p: t.v(),
            l: t.v(),
            x: t.v(),
            y: t.v(),
            lo: t.v(),
            hi: t.v(),
            llo: t.v(),
            lhi: t.v(),
            _pad: [0; 8],
        })
        .unwrap();
    }
    ring
}

/// `P_ema L_ema L_slow ema_ts slow_ts count | b_sec b_lo b_hi b_llo b_lhi | lb_sec lb_lo lb_hi | ring`.
fn parse_state(t: &mut Toks) -> Observation {
    let mut o = Observation::default();
    o.ema.price = t.v();
    o.ema.liq = t.v();
    o.ema.liq_slow = t.v();
    o.ema.ts = t.v();
    o.ema.slow_ts = t.v();
    o.ema.count = t.v();
    if let Some(sec) = t.opt() {
        o.bucket = Bucket {
            sec,
            lo: t.v(),
            hi: t.v(),
            llo: t.v(),
            lhi: t.v(),
            _pad: [0; 8],
        };
    } else {
        for _ in 0..4 {
            assert_eq!(t.s(), "-");
        }
    }
    if let Some(sec) = t.opt() {
        o.last = LastBucket {
            sec,
            lo: t.v(),
            hi: t.v(),
            _pad: [0; 8],
        };
    } else {
        for _ in 0..2 {
            assert_eq!(t.s(), "-");
        }
    }
    o.ring = parse_ring(t);
    o
}

fn assert_state(got: &Observation, want: &Observation, ctx: &str) {
    assert_eq!(got.ema, want.ema, "EMA state, {ctx}");
    assert_eq!(got.bucket, want.bucket, "open bucket, {ctx}");
    assert_eq!(got.last, want.last, "last completed bucket, {ctx}");
    let (g, w): (Vec<_>, Vec<_>) = (got.ring.iter().collect(), want.ring.iter().collect());
    assert_eq!(g, w, "ring, {ctx}");
}

/// `armed count since last`.
fn parse_arm(t: &mut Toks) -> ArmState {
    ArmState {
        armed: u8::from(t.b()),
        count: t.v(),
        since: t.v(),
        last: t.v(),
        _pad: [0; 7],
    }
}

fn parse_box(t: &mut Toks) -> SettleBox {
    SettleBox {
        p_lo: t.v(),
        p_hi: t.v(),
        l_lo: t.v(),
        l_hi: t.v(),
    }
}

// ---------------------------------------------------------------------------------------
// Quotes at the sim's points
// ---------------------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct Point {
    cost: Option<Option<u64>>,
    sigma: Option<u64>,
    fv: Option<Option<u64>>,
}

/// The sim's quotes at the points of one evaluation, keyed by `(P, L)`.
struct TableQuotes {
    map: HashMap<(u128, u128), Point>,
    ctx: String,
}

impl TableQuotes {
    fn put(
        &mut self,
        key: (u128, u128),
        cost: Option<Option<u64>>,
        sigma: Option<Option<u64>>,
        fv: Option<Option<u64>>,
    ) {
        let sigma = sigma.map(|s| s.unwrap_or(u64::MAX));
        let e = self.map.entry(key).or_default();
        let merge = |slot: &mut Option<Option<u64>>, v: Option<Option<u64>>, what: &str| {
            if let Some(v) = v {
                if let Some(old) = *slot {
                    assert_eq!(old, v, "two {what} at {key:?}, {}", self.ctx);
                }
                *slot = Some(v);
            }
        };
        merge(&mut e.cost, cost, "costs");
        merge(&mut e.fv, fv, "FV costs");
        if let Some(s) = sigma {
            if let Some(old) = e.sigma {
                assert_eq!(old, s, "two sigmas at {key:?}, {}", self.ctx);
            }
            e.sigma = Some(s);
        }
    }

    fn get(&self, p: u128, l: u128) -> Point {
        self.map.get(&(p, l)).copied().unwrap_or_default()
    }
}

impl BoxQuotes for TableQuotes {
    fn cost(&mut self, p: u128, l: u128) -> Result<Option<u64>, MathError> {
        Ok(self.get(p, l).cost.unwrap_or_else(|| {
            panic!(
                "cost({p}, {l}) is not a point the sim's rule reads: {}",
                self.ctx
            )
        }))
    }

    fn sigma(&mut self, p: u128, l: u128) -> Result<u64, MathError> {
        Ok(self.get(p, l).sigma.unwrap_or_else(|| {
            panic!(
                "sigma({p}, {l}) is not a point the sim's rule reads: {}",
                self.ctx
            )
        }))
    }

    fn fv_cost(&mut self, p: u128, l: u128) -> Result<Option<u64>, MathError> {
        Ok(self.get(p, l).fv.unwrap_or_else(|| {
            panic!(
                "fv_cost({p}, {l}) is not a point the sim's rule reads: {}",
                self.ctx
            )
        }))
    }
}

// ---------------------------------------------------------------------------------------
// Replay
// ---------------------------------------------------------------------------------------

#[derive(Clone, Copy, Debug)]
struct PosTerms {
    v: u64,
    k_s: u64,
    ert: u64,
    cr_liq_bps: u32,
    penalty_bps: u32,
    sigma_max_bps: u32,
}

#[derive(Default, Debug)]
struct Coverage {
    ops: HashMap<&'static str, usize>,
    kinds: HashMap<SettleKind, usize>,
    arm: HashMap<ArmChange, usize>,
    waits_s2: usize,
    waits_s3: usize,
    wide_boxes: usize,
    point_boxes: usize,
    pprime_fee: usize,
    pprime_penalty: usize,
    /// S2 settlements paid at the expiry fee (`p'` at the EMA point): O15's reading applied
    /// to S2, which SPEC §0 / §5.3 record for S3 only (M0B-S-2).
    s2_expiry_fee: Vec<String>,
    rolls: usize,
    records: usize,
    rewrites: HashMap<&'static str, usize>,
    maxin: HashMap<&'static str, usize>,
    stale_refs: usize,
    /// References on a Raydium venue (the M4F-1 depth cap in `L_b`).
    capped_refs: usize,
    /// Settlement boxes whose `L_mhi` the depth cap bound (AIR-15).
    capped_boxes: usize,
    legs: [usize; 4],
}

#[derive(Clone)]
struct Replay {
    /// A full replay (the trace began with `init`), or decision-only lines.
    full: bool,
    obs: Observation,
    ema_prm: EmaParams,
    exit: ExitParams,
    liq_n: u8,
    eps: u16,
    expiry_fee: u16,
    settle_n: u16,
    arm_gap: u16,
    fv_dev: u32,
    s3: S3Terms,
    pos: HashMap<i64, PosTerms>,
    arms: HashMap<i64, ArmState>,
    /// Per position: `(t, EMA leg)` of its last persistence check.
    chk: HashMap<i64, (i64, bool)>,
    /// `(t, cap)` of a `dcap` op: the depth cap of the box of the settle line that follows
    /// (AIR-15; emitted only where it binds, so every other box is the uncapped one).
    box_cap: Option<(i64, u128)>,
}

impl Replay {
    fn new() -> Self {
        Self {
            box_cap: None,
            full: false,
            obs: Observation::default(),
            ema_prm: EmaParams::DEFAULT,
            exit: ExitParams::DEFAULT,
            liq_n: 3,
            eps: 10,
            expiry_fee: 200,
            settle_n: 40,
            arm_gap: 10,
            fv_dev: 100,
            s3: S3Terms::DEFAULT,
            pos: HashMap::new(),
            arms: HashMap::new(),
            chk: HashMap::new(),
        }
    }

    fn op(&mut self, line: &str, ctx: &str, cov: &mut Coverage) {
        let mut t = Toks::new(line);
        let kind = t.s();
        let ctx = format!("{ctx} [{line}]");
        assert!(
            self.box_cap.is_none() || kind == "settle",
            "a dcap not followed by its settle line, {ctx}"
        );
        let key: &'static str = match kind {
            // prm dtmax clamp slow_tau slow_dtmax | 6 exit terms | liq_n eps fee | settle_n arm_gap fv_dev | s3 terms
            "prm" => {
                self.ema_prm = EmaParams::new(t.v(), t.v(), t.v(), t.v());
                t.bar();
                self.exit = ExitParams {
                    kappa_liq_bps: t.v(),
                    kappa_base_bps: t.v(),
                    delta_liq_bps: t.v(),
                    delta_exp_bps: t.v(),
                    kappa_growth_n: t.v(),
                    ref_max_age_s: t.v(),
                };
                t.bar();
                self.liq_n = t.v();
                self.eps = t.v();
                self.expiry_fee = t.v();
                t.bar();
                self.settle_n = t.v();
                self.arm_gap = t.v();
                self.fv_dev = t.v();
                t.bar();
                self.s3 = S3Terms {
                    s3_wait_s: t.v(),
                    grad_grace_s: t.v(),
                    max_migration_pause_s: t.v(),
                };
                "prm"
            }
            // init t p l
            "init" => {
                self.obs = Observation::new(t.v(), t.v(), t.v()).unwrap();
                self.full = true;
                "init"
            }
            // obs t gap [p l]
            "obs" => {
                let now: i64 = t.v();
                let gap: Option<i64> = t.opt();
                assert_eq!(self.obs.roll(now, &self.ema_prm), Ok(gap), "roll, {ctx}");
                cov.rolls += usize::from(gap.is_some());
                if let Some(p) = t.rest::<u128>() {
                    self.obs.record(now, p, t.v()).unwrap();
                    cov.records += 1;
                }
                "obs"
            }
            // rewrite t g|r l_new | rewrite t R l_new slow_cap (a restart: the anchor, then the
            // marks — M4R's Raydium adoption, `l_new = ⌊D·10⁴/λ_min⌋ > slow_cap = D`, and since
            // M6 / ECON #105 the `→ PumpSwap` graduation as built, `l_new = slow_cap = lp_supply`)
            "rewrite" => {
                let _now: i64 = t.v();
                let kind = t.s();
                let l_new: u128 = t.v();
                let (k, name) = match kind {
                    "g" => (VenueChange::Graduation, "graduation"),
                    "r" => (VenueChange::Raydium, "raydium"),
                    "R" => {
                        let slow_cap: u128 = t.v();
                        let name = if slow_cap == l_new {
                            "graduation_restart"
                        } else {
                            "raydium_restart"
                        };
                        (VenueChange::RaydiumLocked { slow_cap }, name)
                    }
                    k => panic!("unknown venue change {k}"),
                };
                self.obs.rewrite_liquidity(l_new, k).unwrap();
                if kind == "R" {
                    self.obs.mark_restart();
                }
                *cov.rewrites.entry(name).or_default() += 1;
                "rewrite"
            }
            // pos pid Q V K_s ert L penalty slip_max
            "pos" => {
                let pid: i64 = t.v();
                let _q: u64 = t.v();
                let p = PosTerms {
                    v: t.v(),
                    k_s: t.v(),
                    ert: t.v(),
                    cr_liq_bps: t.v(),
                    penalty_bps: t.v(),
                    sigma_max_bps: t.v(),
                };
                self.pos.insert(pid, p);
                "pos"
            }
            // chk t pid flags leg p_live p_rs lo_ok g P_mlo P_mhi L_mlo L_mhi
            "chk" => {
                let (now, pid): (i64, i64) = (t.v(), t.v());
                let flags = t.s();
                let leg = t.b();
                let (p_live, p_rs, lo_ok): (Option<u128>, Option<u128>, bool) =
                    (t.opt(), t.opt(), t.b());
                let g: U256 = t.v();
                let med: (u128, u128, u128, u128) = (t.v(), t.v(), t.v(), t.v());
                let o = &self.obs;
                assert_eq!(flags.len(), o.ring.len(), "flags, {ctx}");
                let mut map = HashMap::new();
                for (e, f) in o.ring.iter().zip(flags.bytes()) {
                    if let Some(old) = map.insert((e.x, e.y), f == b'1') {
                        assert_eq!(old, f == b'1', "inconsistent flags, {ctx}");
                    }
                }
                let below = |x: u128, y: u128| Ok(map[&(x, y)]);
                assert_eq!(
                    liq_ema_leg(&o.ring, below, self.liq_n),
                    Ok(leg),
                    "EMA leg, {ctx}"
                );
                let age = self.exit.ref_max_age_s;
                assert_eq!(o.last.is_fresh(now, age), lo_ok, "fresh bucket, {ctx}");
                let rs = p_live.and_then(|p| robust_spot(p, &o.last, now, age));
                assert_eq!(rs, p_rs, "robust spot, {ctx}");
                let got_g = sustained_growth(&o.ring, self.exit.kappa_growth_n).unwrap();
                assert_eq!(U256::from(got_g), g, "sustained growth, {ctx}");
                assert_eq!(ring_medians(&o.ring), Ok(med), "ring medians, {ctx}");
                self.chk.insert(pid, (now, leg));
                "chk"
            }
            // ref t pid is_liq l_live L_b P_ref
            // ref t pid is_liq l_live L_b P_ref cap (cap: `⌊D·10⁴/λ_min⌋` on Raydium, M4F-1)
            "ref" => {
                let (now, _pid): (i64, i64) = (t.v(), t.v());
                let is_liq = t.b();
                let (l_live, l_b, p_ref): (u128, Option<u128>, Option<u128>) =
                    (t.v(), t.opt(), t.opt());
                let cap: Option<u128> = t.opt();
                cov.capped_refs += usize::from(cap.is_some());
                let o = &self.obs;
                let got = if is_liq {
                    liq_reference(&o.ema, &o.ring, &o.last, now, &self.exit)
                } else {
                    expiry_reference(&o.ema, &o.ring, &o.last, now, &self.exit)
                };
                assert_eq!(got, Ok(p_ref), "P_ref, {ctx}");
                match l_b {
                    Some(l) => {
                        assert_eq!(
                            ref_liquidity(l_live, &o.ema, &o.ring, cap),
                            Ok(l),
                            "L_b, {ctx}"
                        )
                    }
                    None => cov.stale_refs += 1,
                }
                "ref"
            }
            // maxin liq b_ref delta V K_s ert max_in | exp b_ref delta eps fee V K_s R ert pi max_in
            "maxin" => {
                let k = t.s();
                let got = if k == "liq" {
                    let (b, d, v, ks, ert): (u64, u16, u64, u64, u64) =
                        (t.v(), t.v(), t.v(), t.v(), t.v());
                    assert_eq!(d, self.exit.delta_liq_bps, "{ctx}");
                    max_in_liq(b, d, v, ks, ert)
                } else {
                    let (b, d, e, fee): (u64, u16, u16, u16) = (t.v(), t.v(), t.v(), t.v());
                    let (v, ks, r, ert, pi): (u64, u64, u64, u64, u64) =
                        (t.v(), t.v(), t.v(), t.v(), t.v());
                    assert_eq!(
                        (d, e, fee),
                        (self.exit.delta_exp_bps, self.eps, self.expiry_fee),
                        "{ctx}"
                    );
                    assert_eq!(pi_ref(b, fee), Ok(pi), "{ctx}");
                    max_in_exp(b, d, e, v, ks, r, pi, ert)
                };
                assert_eq!(got, t.opt(), "max_in, {ctx}");
                *cov.maxin
                    .entry(if k == "liq" { "liq" } else { "exp" })
                    .or_default() += 1;
                "maxin"
            }
            // dcap t cap (AIR-15: `Market.ref_depth_cap`, binding on the next settle line's box)
            "dcap" => {
                assert!(self.full, "dcap in a decision-only trace, {ctx}");
                self.box_cap = Some((t.v(), t.v()));
                "dcap"
            }
            "settle" => {
                self.settle(&mut t, &ctx, cov);
                "settle"
            }
            // state <full observation state>
            "state" => {
                assert_state(&self.obs, &parse_state(&mut t), &ctx);
                "state"
            }
            k => panic!("unknown op {k}, {ctx}"),
        };
        t.done();
        *cov.ops.entry(key).or_default() += 1;
    }

    /// One settlement evaluation (layout in `gen_settle.py`).
    fn settle(&mut self, t: &mut Toks, ctx: &str, cov: &mut Coverage) {
        let (now, pid): (i64, i64) = (t.v(), t.v());
        let path = t.s();
        let deadline: i64 = t.v();
        t.bar();
        let (ema_count, p_ema, l_ema, ema_ts): (u64, u128, u128, i64) =
            (t.v(), t.v(), t.v(), t.v());
        t.bar();
        let bx = parse_box(t);
        t.bar();
        let r_due: u64 = t.v();
        let (cr_liq, ema_leg, exec) = (t.b(), t.b(), t.b());
        let (p_rs, l_live, b_live): (Option<u128>, u128, Option<u64>) = (t.opt(), t.v(), t.opt());
        let sigma_live = t.rec::<u64>().map_or(u64::MAX, |s| s.unwrap_or(u64::MAX));
        t.bar();
        let s3 = S3Chain {
            no_route_now: t.b(),
            no_route_since: t.opt(),
            graduated_at: t.opt(),
            migrating: t.b(),
            migration_seen_at: t.opt(),
        };
        t.bar();
        let mut q = TableQuotes {
            map: HashMap::new(),
            ctx: ctx.to_owned(),
        };
        let (ca, sa, fa, cb, fb, sc, cd, sd, fe) = (
            t.rec::<u64>(),
            t.rec::<u64>(),
            t.rec::<u64>(),
            t.rec::<u64>(),
            t.rec::<u64>(),
            t.rec::<u64>(),
            t.rec::<u64>(),
            t.rec::<u64>(),
            t.rec::<u64>(),
        );
        q.put((bx.p_lo, bx.l_hi), ca, sa, fa);
        q.put((bx.p_hi, bx.l_lo), cb, None, fb);
        q.put((bx.p_hi, l_live.min(bx.l_lo)), None, sc, None);
        if let Some(p) = p_rs {
            q.put((p, l_live), cd, sd, None);
        } else {
            assert!(
                cd.is_none() && sd.is_none(),
                "robust-spot quotes without P_rs, {ctx}"
            );
        }
        q.put((p_ema, l_ema), None, None, fe);
        t.bar();
        let (nl, rf, s1, s2) = (t.ob(), t.ob(), t.ob(), t.ob());
        t.bar();
        let before = parse_arm(t);
        t.bar();
        let after = parse_arm(t);
        t.bar();
        let kind = t.s();
        let (lenders, borrower): (Option<u64>, Option<u64>) = (t.opt(), t.opt());
        let (fv, pp): (Option<u64>, Option<u32>) = (t.opt(), t.opt());
        let corners: [(Option<u64>, Option<u64>, Option<u32>); 2] =
            [(t.opt(), t.opt(), t.opt()), (t.opt(), t.opt(), t.opt())];
        t.bar();
        let (w2, w3) = (t.b(), t.b());

        let p = *self.pos.get(&pid).expect("settle before pos");
        let budget = Budget {
            v: p.v,
            k_s: p.k_s,
            ert: p.ert,
        };
        let cap = self.box_cap.take().map(|(at, cap)| {
            assert_eq!(at, now, "the dcap of another second, {ctx}");
            cap
        });
        if self.full {
            let o = &self.obs;
            assert_eq!(
                (o.ema.count, o.ema.price, o.ema.liq, o.ema.ts),
                (ema_count, p_ema, l_ema, ema_ts),
                "EMA state at the evaluation, {ctx}"
            );
            assert_eq!(
                box_of_capped(&o.ema, &o.ring, now, exec, cap),
                Ok(bx),
                "settlement box, {ctx}"
            );
            if cap.is_some() {
                // AIR-15: the cap binds (only then does the generator emit it).
                assert_ne!(box_of(&o.ema, &o.ring, now, exec), Ok(bx), "{ctx}");
                cov.capped_boxes += 1;
            }
            assert_eq!(self.chk.get(&pid), Some(&(now, ema_leg)), "EMA leg, {ctx}");
            let tracked = self.arms.get(&pid).copied().unwrap_or_default();
            assert_eq!(tracked, before, "arm state before, {ctx}");
        } else if now - ema_ts > 8 && !exec {
            assert!(
                bx.is_point() && bx.p_lo == p_ema && bx.l_lo == l_ema,
                "{ctx}"
            );
        }
        cov.wide_boxes += usize::from(!bx.is_point());
        cov.point_boxes += usize::from(bx.is_point());

        let terms = SettleTerms {
            cr_liq_bps: p.cr_liq_bps,
            sigma_max_bps: p.sigma_max_bps,
            penalty_bps: p.penalty_bps,
            expiry_fee_bps: u32::from(self.expiry_fee),
            fv_dev_bps: self.fv_dev,
            persist_n: self.settle_n,
            arm_gap_s: self.arm_gap,
            s3: self.s3,
        };
        let inp = SettleInputs {
            now,
            deadline,
            ema_count,
            p_ema,
            l_ema,
            bx,
            budget,
            r_due,
            cr_liquidatable: cr_liq,
            ema_leg,
            executable: exec,
            warmed: shortwin_math::observe::warmed(&self.obs.ema),
            p_rs,
            l_live,
            b_live,
            sigma_live,
            s3,
        };
        let expired = inp.expired();
        let v_eff = inp.v_eff();

        // The sim's intermediate decisions, each through the crate's own predicate.
        if let Some(want) = nl {
            let got = not_liquidatable(&mut q, expired, ema_leg, v_eff, p.cr_liq_bps, &bx);
            assert_eq!(got, Ok(want), "not liquidatable, {ctx}");
        }
        if let Some(want) = rf {
            let got = refuted(&mut q, &budget, p.sigma_max_bps, l_live, &bx);
            assert_eq!(got, Ok(want), "refuted, {ctx}");
        }
        if let Some(want) = s1 {
            let got = s1_legs(&mut q, &budget, b_live, p_rs.unwrap(), l_live, &bx);
            assert_eq!(got, Ok(want), "S1 legs, {ctx}");
            cov.legs[usize::from(want)] += 1;
        }
        if let Some(want) = s2 {
            let got = s2_legs(
                &mut q,
                p.sigma_max_bps,
                sigma_live,
                p_rs.unwrap(),
                l_live,
                &bx,
            );
            assert_eq!(got, Ok(want), "S2 legs, {ctx}");
            cov.legs[2 + usize::from(want)] += 1;
        }

        let mut state = before;
        let e = evaluate(&mut state, &inp, &terms, &mut q).unwrap();
        assert_eq!(state, after, "arm state after, {ctx}");
        match e.arm {
            ArmChange::None => assert_eq!(state, before, "{ctx}"),
            ArmChange::Kept => {
                assert!(state.armed == 1 && state.last == now, "{ctx}");
                assert_eq!(
                    (state.count, state.since),
                    (before.count, before.since),
                    "{ctx}"
                );
            }
            ArmChange::Armed => {
                assert_eq!(
                    (state.armed, state.count, state.since),
                    (1, ema_count, now),
                    "{ctx}"
                )
            }
            ArmChange::Disarmed(why) => {
                assert!(before.armed == 1 && state.armed == 0, "{ctx}");
                let want = if path == "N" {
                    DisarmReason::NotLiquidatable
                } else {
                    DisarmReason::Refuted
                };
                assert_eq!(why, want, "{ctx}");
            }
        }
        *cov.arm.entry(e.arm).or_default() += 1;
        assert_eq!((e.s2_waited, e.s3_waited), (w2, w3), "amount waits, {ctx}");
        cov.waits_s2 += usize::from(w2);
        cov.waits_s3 += usize::from(w3);
        match (kind, e.settlement) {
            ("-", None) => {}
            (k, Some(s)) => {
                let want_kind = match k {
                    "S1" => SettleKind::S1,
                    "S2" => SettleKind::S2,
                    "S3" => SettleKind::S3,
                    k => panic!("unknown kind {k}, {ctx}"),
                };
                assert_eq!(s.kind, want_kind, "kind, {ctx}");
                assert_eq!(
                    (Some(s.lenders), Some(s.borrower)),
                    (lenders, borrower),
                    "{ctx}"
                );
                assert_eq!(s.k_s, p.k_s, "{ctx}");
                assert_eq!((s.fv, s.pprime), (fv, pp), "FV at the EMA point, {ctx}");
                if k == "S2" && pp == Some(terms.expiry_fee_bps) && pp != Some(terms.penalty_bps) {
                    // The location, without the vector line.
                    let at = ctx.split_once(" [").map_or(ctx, |(at, _)| at);
                    cov.s2_expiry_fee.push(at.to_owned());
                }
                match s.corners {
                    None => assert!(k == "S1" && corners.iter().all(|c| c.0.is_none()), "{ctx}"),
                    Some([lo, hi]) => {
                        let got = [
                            (Some(lo.x), lo.fv, lo.pprime),
                            (Some(hi.x), hi.fv, hi.pprime),
                        ];
                        assert_eq!(got, corners, "box corners, {ctx}");
                        for c in [lo, hi] {
                            match c.pprime {
                                Some(x) if x == terms.expiry_fee_bps && x != terms.penalty_bps => {
                                    cov.pprime_fee += 1
                                }
                                Some(_) => cov.pprime_penalty += 1,
                                None => {}
                            }
                        }
                    }
                }
                *cov.kinds.entry(s.kind).or_default() += 1;
            }
            (k, None) => panic!("the sim settled {k}, the crate did not: {ctx}"),
        }
        if self.full {
            self.arms.insert(pid, state);
        }
    }
}

#[derive(Deserialize)]
struct TraceFile {
    generator: String,
    traces: Vec<Trace>,
}

#[derive(Deserialize)]
struct Trace {
    name: String,
    ops: Vec<String>,
    base: Option<String>,
}

/// Replays every `settle/<prefix>_<k>.json`, in order; a trace with a `base` continues the
/// replayed state of that earlier trace.
fn replay(prefix: &str) -> (Coverage, usize) {
    let mut cov = Coverage::default();
    let mut ends: HashMap<String, Replay> = HashMap::new();
    let mut traces = 0;
    for k in 1.. {
        let file = format!("{prefix}_{k}.json");
        if !common::vectors_dir().join("settle").join(&file).exists() {
            assert!(k > 1, "no {file}");
            break;
        }
        let f: TraceFile = common::load_vectors("settle", &file);
        assert_eq!(f.generator, "gen_settle.py");
        for tr in &f.traces {
            let mut r = match &tr.base {
                Some(b) => ends
                    .get(b)
                    .unwrap_or_else(|| panic!("base {b} not replayed"))
                    .clone(),
                None => Replay::new(),
            };
            for (i, op) in tr.ops.iter().enumerate() {
                r.op(op, &format!("{file} / {} / op {i}", tr.name), &mut cov);
            }
            ends.insert(tr.name.clone(), r);
            traces += 1;
        }
    }
    (cov, traces)
}

fn n(c: &Coverage, k: SettleKind) -> usize {
    c.kinds.get(&k).copied().unwrap_or(0)
}

fn arms(c: &Coverage, a: ArmChange) -> usize {
    c.arm.get(&a).copied().unwrap_or(0)
}

