#[derive(Deserialize)]
struct UnitsSettle {
    generator: String,
    #[serde(rename = "box")]
    box_: Vec<String>,
    box_exec: Vec<String>,
    box_cap: Vec<String>,
    s3: Vec<String>,
}

/// `Market.settle_box` on synthetic rings: the medians of the bucket extremes and, on a
/// venue that cannot execute (`box`), the EMA point after `RING_LEN` seconds without an
/// integration; on an executable venue (`box_exec`) never the EMA point alone (M2-SEC-1);
/// with a depth cap on `L_mhi` (`box_cap`, AIR-15).
#[test]
fn settle_box_matches_sim() {
    let f: UnitsSettle = common::load_vectors("settle", "units_settle.json");
    assert_eq!(f.generator, "gen_settle.py");
    assert!(f.box_.len() >= 200 && f.box_exec.len() >= 200);
    for (exec, lines) in [(false, &f.box_), (true, &f.box_exec)] {
        let (mut points, mut wide, mut stale_wide) = (0, 0, 0);
        for (i, line) in lines.iter().enumerate() {
            let ctx = format!("box case {i} (executable {exec}): {line}");
            let mut t = Toks::new(line);
            let now: i64 = t.v();
            let mut o = Observation::default();
            o.ema.price = t.v();
            o.ema.liq = t.v();
            o.ema.ts = t.v();
            let want = parse_box(&mut t);
            o.ring = parse_ring(&mut t);
            t.done();
            assert_eq!(box_of(&o.ema, &o.ring, now, exec), Ok(want), "{ctx}");
            points += usize::from(want.is_point());
            wide += usize::from(!want.is_point());
            stale_wide += usize::from(now - o.ema.ts > 8 && !want.is_point());
        }
        if exec {
            // The M2-SEC-1 branch: stale integrations on an executable venue keep the medians.
            assert!(
                stale_wide >= 60 && wide >= 200,
                "{wide} boxes, {stale_wide} stale"
            );
        } else {
            assert!(points >= 30 && wide >= 100, "{points} points, {wide} boxes");
            assert_eq!(stale_wide, 0);
        }
    }
    // AIR-15: `L_hi = max(L_ema, min(L_mhi, cap))`, the rest of the box unchanged.
    assert!(f.box_cap.len() >= 200);
    let (mut binding, mut below_ema) = (0, 0);
    for (i, line) in f.box_cap.iter().enumerate() {
        let ctx = format!("capped box case {i}: {line}");
        let mut t = Toks::new(line);
        let now: i64 = t.v();
        let exec = t.b();
        let cap: u128 = t.v();
        let mut o = Observation::default();
        o.ema.price = t.v();
        o.ema.liq = t.v();
        o.ema.ts = t.v();
        let want = parse_box(&mut t);
        o.ring = parse_ring(&mut t);
        t.done();
        assert_eq!(
            box_of_capped(&o.ema, &o.ring, now, exec, Some(cap)),
            Ok(want),
            "{ctx}"
        );
        let plain = box_of(&o.ema, &o.ring, now, exec).unwrap();
        assert_eq!(
            SettleBox {
                l_hi: plain.l_hi,
                ..want
            },
            plain,
            "{ctx}"
        );
        assert!(
            want.l_hi <= plain.l_hi && want.contains(o.ema.price, o.ema.liq),
            "{ctx}"
        );
        binding += usize::from(want.l_hi < plain.l_hi);
        below_ema += usize::from(!want.is_point() && cap < o.ema.liq);
    }
    assert!(
        binding >= 60 && below_ema >= 20,
        "{binding} binding, {below_ema} below L_ema"
    );
}

/// `Market._s3_due` on synthetic chains (graduation grace, migration pause, a broken or
/// missing chain).
#[test]
fn s3_timer_matches_sim() {
    let f: UnitsSettle = common::load_vectors("settle", "units_settle.json");
    assert!(f.s3.len() >= 200);
    let mut due = 0;
    for line in &f.s3 {
        let mut t = Toks::new(line);
        let now: i64 = t.v();
        let chain = S3Chain {
            no_route_now: t.b(),
            no_route_since: t.opt(),
            graduated_at: t.opt(),
            migrating: t.b(),
            migration_seen_at: t.opt(),
        };
        let liq_or_exp = t.b();
        let terms = S3Terms {
            s3_wait_s: t.v(),
            grad_grace_s: t.v(),
            max_migration_pause_s: t.v(),
        };
        let want = t.b();
        t.done();
        assert_eq!(s3_due(&chain, &terms, now, liq_or_exp), want, "{line}");
        due += usize::from(want);
    }
    assert!(due >= 30, "{due} due");
}

/// `try_exit(settle_only = True)` on synthetic states: every branch of ARCH §3.8 with the
/// quotes, the budget, σ_max, the CR, the amount tolerance, the arm gap and the persistence
/// count at and around their boundaries; a migrating venue's FV on the post-migration pool.
#[test]
fn evaluate_matches_sim_on_synthetic_states() {
    let (c, traces) = replay("units_evaluate");
    assert!(traces >= 1_000, "{traces}");
    assert!(
        n(&c, SettleKind::S1) >= 10 && n(&c, SettleKind::S2) >= 10 && n(&c, SettleKind::S3) >= 50,
        "{c:?}"
    );
    assert!(c.waits_s2 >= 5 && c.waits_s3 >= 10, "{c:?}");
    for a in [
        ArmChange::None,
        ArmChange::Kept,
        ArmChange::Armed,
        ArmChange::Disarmed(DisarmReason::Refuted),
        ArmChange::Disarmed(DisarmReason::NotLiquidatable),
    ] {
        assert!(arms(&c, a) >= 10, "{a:?}: {c:?}");
    }
    assert!(c.pprime_fee >= 5 && c.pprime_penalty >= 20, "{c:?}");
    assert!(c.legs.iter().all(|&k| k >= 50), "{:?}", c.legs);
}

/// The attack scripts of ECON §12 (v0.4.1 rows): arming (§12.10), blocking the spot leg
/// (§12.9), the refutation push, the spot-leg veto, push-then-freeze and widening (§12.10),
/// the FV push, the S2 → S1 flip, push-then-freeze, consecutive attacker-only seconds, the
/// `p'` veto and the Emergency-flag S3 (§12.11), the fixed-δ sandwich (§12.2), the
/// push-then-freeze sandwich (R4B-2) and the venue-change ring rewrite (A72).
#[test]
fn attack_traces_match_sim() {
    let (c, traces) = replay("trace_attacks");
    assert!(traces >= 50, "{traces}");
    assert!(
        n(&c, SettleKind::S1) >= 15 && n(&c, SettleKind::S2) >= 4 && n(&c, SettleKind::S3) >= 8,
        "{c:?}"
    );
    assert!(c.waits_s3 >= 20 && c.wide_boxes >= 1_000, "{c:?}");
    assert!(arms(&c, ArmChange::Armed) >= 15, "{c:?}");
    assert!(c.pprime_fee >= 2, "{c:?}");
    // The venue-change rewrites (A72): the Raydium adoption's restart (M4R) and, since M6 / ECON
    // #105, the graduation's restart as built (v0.4.1's `g` rewrite no trace emits any more).
    assert!(
        c.rewrites.len() == 2
            && c.rewrites.contains_key("raydium_restart")
            && c.rewrites.contains_key("graduation_restart"),
        "{:?}",
        c.rewrites
    );
    assert!(c.maxin.get("liq").copied().unwrap_or(0) >= 5, "{c:?}");
    assert!(c.ops.get("state").copied().unwrap_or(0) >= 100, "{c:?}");
    // M4F-1: references on Raydium markets carry the depth cap.
    assert!(c.capped_refs >= 5, "{c:?}");
    // AIR-15: boxes whose L_mhi the depth cap bound (the RA markets; widen-LP's wrapped highs).
    assert!(c.capped_boxes >= 300, "{c:?}");
}

/// ECON §11.2 scenarios (gaps, a fast pump, a drain then a pump, a spike, a disabled pool,
/// the Emergency flag, expiries, a stuck migration settled in S3 on the post-migration
/// pool), genuine reversals of an armed S1 (box refutation; box "not liquidatable") and S3
/// on a halted pool (the box collapsed to the EMA point).
#[test]
fn scenario_traces_match_sim() {
    let (c, traces) = replay("trace_scenarios");
    assert!(traces >= 15, "{traces}");
    assert!(
        n(&c, SettleKind::S1) >= 1 && n(&c, SettleKind::S3) >= 3,
        "{c:?}"
    );
    for why in [DisarmReason::Refuted, DisarmReason::NotLiquidatable] {
        assert!(arms(&c, ArmChange::Disarmed(why)) >= 3, "{why:?}: {c:?}");
    }
    assert!(c.point_boxes >= 100 && c.rolls >= 2_000, "{c:?}");
    assert!(c.maxin.get("exp").copied().unwrap_or(0) >= 2, "{c:?}");
    assert!(c.capped_refs >= 2, "{c:?}");
    assert!(c.capped_boxes >= 50, "{c:?}");
}

/// The first six runs of ECON §13's exit fuzz, replayed whole (attacker bundles, blockers,
/// pushers, freezers, sandwiches, per-second noise).
#[test]
fn random_traces_match_sim() {
    let (c, traces) = replay("trace_random");
    assert_eq!(traces, 6);
    assert!(c.rolls >= 3_000 && c.records >= 6_000, "{c:?}");
    assert!(c.ops.get("settle").copied().unwrap_or(0) >= 100, "{c:?}");
}

/// ECON §13's exit fuzz, 1,000 paths (`fuzz_exits(1000, 20260927)`): every settlement,
/// wait, arming and disarm, the vetoes and a sample of the clock's ticks, each decision
/// checked on the sim's box and quotes. The totals are the sim's since AIR-22's lower-median
/// growth (S1 / S2 / S3 = 147 / 10 / 35; ECON §13 published 174 / 8 / 28 before it).
#[test]
fn exit_fuzz_decisions_match_sim() {
    let (c, traces) = replay("fuzz");
    assert!(traces >= 500, "{traces}");
    assert_eq!(
        (
            n(&c, SettleKind::S1),
            n(&c, SettleKind::S2),
            n(&c, SettleKind::S3)
        ),
        (147, 10, 35),
        "ECON §13 exit fuzz kinds"
    );
    assert!(c.waits_s2 + c.waits_s3 >= 100, "{c:?}");
    assert!(arms(&c, ArmChange::Armed) >= 150, "{c:?}");
    assert!(c.maxin.values().sum::<usize>() >= 4_000, "{c:?}");
    // M0B-S-2 (review; owner item O15): the sim's `fv_parts` takes the expiry fee for any
    // S2 or S3 of an expired position that is not CR-liquidatable at the evaluated state;
    // SPEC §0 / §5.3 and ARCH §10 record O15 for S3 only. Three fuzz paths reach the S2 case
    // (one before AIR-22 redrew the fuzz's later runs; run 52 is unchanged).
    assert_eq!(
        c.s2_expiry_fee,
        [
            "fuzz_1.json / fuzz/52 / op 119",
            "fuzz_1.json / fuzz/99 / op 89",
            "fuzz_1.json / fuzz/327 / op 75"
        ],
        "S2 at the expiry fee"
    );
}

/// M0B-S-2 (review; owner item O15): ECON §13's exit fuzz run 52 settles a Tier A position
/// in **S2** after its deadline, not CR-liquidatable at the EMA point, so the sim prices
/// FV at the expiry fee (p' = 200, FV 69,021,636,745; `fuzz_1.json`, `fuzz/52`, op 119).
/// The SPEC-literal reading of O15 (expiry fee in S3 only) would take the penalty (p' =
/// 500, FV 70,977,058,967, i.e. 1.96 SOL more to the lenders). The crate follows the sim;
/// this test pins the reading until the owner confirms it (README, Open decisions).
#[test]
fn o15_reading_applies_to_an_expired_s2() {
    use shortwin_math::risk::fair_value;
    use shortwin_math::settle::pprime;
    let (v, r_due, b_fv) = (127_741_241_290u64, 2_537_281_202u64, 65_180_740_728u64);
    let v_eff = v - r_due;
    // Expired and CR(V_eff, B̂_FV) ≥ L = 12,500 at the EMA point: the expiry fee.
    assert!(u128::from(v_eff) * 10_000 >= u128::from(b_fv) * 12_500);
    assert_eq!(pprime(true, v_eff, b_fv, 12_500, 500, 200), 200);
    assert_eq!(fair_value(Some(b_fv), 200, r_due), Some(69_021_636_745));
    // The penalty reading (not expired, or SPEC-literal S2): p' = 500.
    assert_eq!(pprime(false, v_eff, b_fv, 12_500, 500, 200), 500);
    assert_eq!(fair_value(Some(b_fv), 500, r_due), Some(70_977_058_967));
    assert_eq!(70_977_058_967u64 - 69_021_636_745, 1_955_422_222);
}
